// Check if we have any free blocks in the lookahead buffer
if (lfs->free.off == lfs->free.size) {
    // If not, scan for more free blocks
    lfs->free.off = 0;
    lfs->free.size = 0;

    // Start from the last block we found
    lfs_block_t block = lfs->free.block;
    lfs_block_t off = lfs->free.off;
    lfs_size_t i = 0;

    // Scan through the lookahead buffer
    for (; i < lfs_min(lfs->cfg->lookahead_size * 8, lfs->block_count - block); i++) {
        // Check if block is free
        if (!(lfs->free.buffer[i / 8] & (1U << (i % 8)))) {
            // Found a free block
            if (off == 0) {
                // Start a new run
                lfs->free.block = block + i;
            }
            off++;
        } else {
            // Block is not free, end current run
            if (off > 0) {
                // Update lookahead buffer
                lfs->free.buffer[lfs->free.size / 8] |= 1U << (lfs->free.size % 8);
                lfs->free.size++;
                off = 0;
            }
        }
    }

    // Update lookahead state
    lfs->free.off = 0;
    if (off > 0) {
        // We have a partial run at the end
        lfs->free.buffer[lfs->free.size / 8] |= 1U << (lfs->free.size % 8);
        lfs->free.size++;
    }

    // Check if we found any free blocks
    if (lfs->free.size == 0) {
        return LFS_ERR_NOSPC;
    }
}

// Allocate a block from the lookahead buffer
*block = lfs->free.block + lfs->free.off;

// Update lookahead state
lfs->free.off++;
if (lfs->free.off >= lfs->free.size) {
    lfs->free.off = 0;
    lfs->free.size = 0;
    lfs->free.block = *block + 1;
}

// Update wear leveling state
if (lfs->cfg->block_cycles > 0) {
    lfs->wear[(*block) / 32] += 1U << ((*block) % 32);
}

// Mark block as used in lookahead buffer
lfs_size_t index = (*block - lfs->free.block + lfs->free.off - 1) % lfs->cfg->lookahead_size;
lfs->free.buffer[index / 8] &= ~(1U << (index % 8));

return 0;

